scwin.gUpjongJongmok = ""; //업종에 따른 종목

	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.gFilterType = ""; //"S":종목검색버튼,"O"
scwin.gJongName = ""; //종목명
scwin.ssMarket = "N"; //종목콤보확인

scwin.stat = "";

	//----W-Craft WebSquare 변환 확인: Provider----//
scwin.tpcd = frame.Provider("../").js_com_market;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; //세션의 시장구분
scwin.fn_list_sync = function() {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var url = "/submitperson.do?method=searchSubmitPerson&inputMessageId=submitperson&outputMessageId=submitperson&DISCLS_SUBMITPRN_TP_CD=" + MxDataSet_code1.NameValue(combo_market.Index + 1, "CD_VAL");
    //alert(url); 
    txb_jongmokName.setValue("");
    dts_jongmok.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_jongmok.reset();
    $c.cm.ShowWin(grd_jongmok);
};


/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.UseFilter = "true";

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.SortExpr = "+SUBMIT_OBLG_ABBRV";
    dts_jongmok.Sort();
    var cnt = 0;
    for (i = 1; i <= dts_jongmok.countrow; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        var name = dts_jongmok.NameValue(i, "SUBMIT_OBLG_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.Rowposition = cnt + 11;
    dts_jongmok.Rowposition = cnt;

	//----W-Craft WebSquare 변환 확인: focus----//
    grd_jongmok.focus();
};


/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.SortExpr = "+SUBMIT_OBLG_ABBRV";
    dts_jongmok.Sort();
    var cnt = 0;
    var len = txb_jongmokName.getValue().length;
    var txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.countrow; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        var name = dts_jongmok.NameValue(i, "SUBMIT_OBLG_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.Rowposition = cnt + 11;
    dts_jongmok.Rowposition = cnt;
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.skw = "";
$c.stockSearch.JongmokSearch = function() {
    scwin.skw = txb_jongmokName.getValue();

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.UseFilter = "true";

	//----W-Craft WebSquare 변환 확인: Filter----//
    dts_jongmok.Filter();
    dts_jongmok.Rowposition = 1;
};


/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = function() {
    //frame.Provider("../").종목코드id

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var pJongCode = dts_jongmok.NameValue(dts_jongmok.RowPosition, "SUBMIT_OBLG_ABBRV");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var pJongNm = dts_jongmok.NameValue(dts_jongmok.RowPosition, "DISCLS_SUBMITPRN_TP_CD_NM");
    $c.cm.submitSearch_Rtn(pJongCode, pJongNm);

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
    frame.CloseFrame();
};
scwin.fn_code1_sync = function() {
    var url1 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=00967";
    MxDataSet_code1.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
};



