scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    $c.libRoundPanel.PanelToGroupBox_02(panel_2);
    dts_jongmok.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=isurcd";

	//----W-Craft WebSquare 변환 확인: reset----//
