	//----W-Craft WebSquare 변환 확인: Filter----//
scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw !== "") {

	//----W-Craft WebSquare 변환 확인: NameString----//
        f1 = dts_jongmok.NameString(row, "COM_ABBRV");

	//----W-Craft WebSquare 변환 확인: NameString----//
        f2 = dts_jongmok.NameString(row, "OLD_COM_ABBRV");
        if (f1.indexOf(scwin.skw) !== -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) !== -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
